const cfg = $json;
const page = String($('Page Request').first().json.params.page || '');
let body = 'Not found', type = 'text/plain; charset=utf-8', status = 404;
if (page === 'privacy') { body = cfg.PRIVACY_HTML; type = 'text/html; charset=utf-8'; status = 200; }
else if (page === 'terms') { body = cfg.TERMS_HTML; type = 'text/html; charset=utf-8'; status = 200; }
else if (page === cfg.TIKTOK_VERIFY_FILENAME) { body = cfg.TIKTOK_VERIFY_CONTENT; status = 200; }
return [{ json: { body, type, status } }];
